"""Render a standalone, offline searchable catalogue."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'汇总/2026-10-13'
rows=json.loads((OUT/'岗位与线索总表.json').read_text())
stats=json.loads((OUT/'统计.json').read_text())
# Keep full JD in JSON/Excel; browser view includes useful excerpts to stay responsive.
compact=[]
for r in rows:
 r=dict(r);r['requirements']=r.get('requirements','')[:1500];r['duties']=r.get('duties','')[:600];compact.append(r)
data=json.dumps(compact,ensure_ascii=False).replace('<','\\u003c')
template='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>金融校招机会总览 · 2026-10-13</title>
<style>:root{--ink:#17374b;--muted:#667b87;--accent:#097969}*{box-sizing:border-box}body{margin:0;background:#f4f6f5;color:var(--ink);font:15px/1.65 system-ui,-apple-system,"Microsoft YaHei",sans-serif}header{background:#17374b;color:#fff;padding:42px max(5vw,20px)}header small{letter-spacing:2px;color:#9ed3c7}h1{font-size:34px;margin:10px 0}header p{max-width:950px;color:#d5e0e7}main{margin:24px auto;width:90%;max-width:1600px}.cards{display:flex;gap:16px;flex-wrap:wrap}.card{background:#fff;border:1px solid #dbe4e3;padding:20px 26px;min-width:190px;border-radius:12px;flex:1}.card strong{display:block;font-size:32px}.note{padding:16px;background:#e8f1ed;border-radius:8px;margin:18px 0}.filters{display:flex;gap:10px;flex-wrap:wrap;margin:22px 0;position:sticky;top:0;background:#f4f6f5;padding:12px 0;z-index:2}input,select,button{border:1px solid #c9d5d6;padding:11px 13px;border-radius:7px;background:#fff;color:var(--ink);font:inherit}input{min-width:260px;flex:2}button{cursor:pointer}button:hover{border-color:var(--accent)}a{color:var(--accent);text-decoration:none}a:hover{text-decoration:underline}.links{display:flex;gap:18px;margin:16px 0}.tablewrap{overflow-x:auto;background:#fff;border-radius:10px;border:1px solid #dbe4e3}table{width:100%;border-collapse:collapse}th{text-align:left;background:#e7eeed;white-space:nowrap;padding:14px}td{vertical-align:top;padding:14px;border-top:1px solid #edf0ee;max-width:450px;min-width:100px}td.title{min-width:300px}.sub{font-size:12px;color:var(--muted)}.badge{display:inline-block;padding:3px 8px;border-radius:20px;background:#eef3f1;font-size:12px}.open{color:#097969;background:#e7f6ee}.closed{color:#9c5a44;background:#fcf0e8}details{font-size:13px;max-width:500px}details p{white-space:pre-wrap}summary{cursor:pointer;color:var(--accent);margin-top:8px}.pager{display:flex;align-items:center;gap:15px;justify-content:center;margin:22px}.empty{padding:45px;text-align:center}footer{color:var(--muted);padding:25px 0;font-size:13px}@media(max-width:700px){h1{font-size:26px}main{width:94%}.card{min-width:140px;padding:12px}.card strong{font-size:25px}.filters{position:static}input{min-width:100%}}</style>
<header><small>FINANCIAL CAMPUS OPPORTUNITIES</small><h1>金融校招机会总览</h1><p>全国金融行业 · 校招 / 秋招 / 转正实习线索 · 总行、分支机构与关联公司 · 采集日期 2026-10-13</p><p>从官方职位列表、招聘公告和公开聚合源整理。先看“具体岗位”，再按地区与方向搜索；完整职责和要求保存在 Excel / JSON 中。</p></header><main>
<div class="cards"><div class="card">具体岗位记录<strong>__JOBS__</strong></div><div class="card">公告期限内记录<strong>__OPEN__</strong></div><div class="card">聚合招聘线索<strong>__LEADS__</strong></div><div class="card">全部记录<strong>__TOTAL__</strong></div></div>
<div class="note">“公告期限内”仅表示明确日期尚未到期，不保证岗位未提前招满或你满足资格；空日期与系统占位日期均标记待核实。清单包括历史届别与已截止批次，可用筛选器排除。招聘项目、岗位类别和具体岗位分别统计。</div>
<div class="links"><a href="金融校招岗位大全.xlsx">下载 Excel</a><a href="岗位与线索总表.csv">下载 CSV</a><a href="岗位与线索总表.json">完整 JSON</a><a href="覆盖与缺口.md">覆盖与缺口</a></div>
<div class="filters"><input id="query" type="search" placeholder="搜索：机构 / Python / 量化 / 城市 / 岗位ID" aria-label="搜索岗位"><select id="type" aria-label="记录类型"></select><select id="track" aria-label="赛道"></select><select id="status" aria-label="招聘状态"></select><select id="year" aria-label="届别"><option value="">全部届别</option><option value="2027">明确标记2027</option><option value="unknown">届别待核实</option><option value="history">历史届别</option></select><button id="reset">重置</button></div>
<p id="count"></p><div class="tablewrap"><table><thead><tr><th>机构 / 单位</th><th>岗位 / 项目</th><th>地点 / 届别</th><th>截止与状态</th><th>来源与入口</th></tr></thead><tbody id="body"></tbody></table><div class="empty" id="empty" hidden>没有符合条件的记录。试试减少筛选条件。</div></div><div class="pager"><button id="prev">上一页</button><span id="page"></span><button id="next">下一页</button></div>
<footer>统计单位为岗位或信息记录，不是招聘人数；同一品牌的不同部门和城市保留。官方接口以稳定职位ID去重，跨源公告与岗位有层级重叠，尚未做完整语义合并。此文件可离线打开，检索不会上传个人信息。</footer></main>
<script>const rows=__DATA__;let page=1;const size=60;let filtered=[];const $=id=>document.getElementById(id);function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}function link(u,label){try{let x=new URL(u);if(!['https:','http:'].includes(x.protocol))return '';return '<a target="_blank" rel="noopener noreferrer" href="'+esc(u)+'">'+label+'</a>';}catch{return '';}}
for(const [id,key,label] of [['type','record_type','全部类型'],['track','track','全部赛道'],['status','status','全部状态']]){$(id).innerHTML='<option value="">'+label+'</option>'+[...new Set(rows.map(r=>r[key]))].sort().map(v=>'<option>'+esc(v)+'</option>').join('');}
const searchable=rows.map(r=>[r.org,r.org_unit,r.title,r.locations,r.requirements,r.official_job_id].join(' ').toLowerCase());
function filter(){page=1;const q=$('query').value.toLowerCase().trim().split(/\\s+/).filter(Boolean);filtered=rows.filter((r,i)=>(!$('type').value||r.record_type===$('type').value)&&(!$('track').value||r.track===$('track').value)&&(!$('status').value||r.status===$('status').value)&&(!$('year').value||($('year').value==='2027'?r.recruitment_cycle.includes('2027'):$('year').value==='history'?r.recruitment_cycle.includes('2026或更早'):r.recruitment_cycle.includes('待核实')))&&q.every(t=>searchable[i].includes(t)));render();}
function render(){const total=Math.max(1,Math.ceil(filtered.length/size));page=Math.min(page,total);$('count').textContent='筛选结果 '+filtered.length+' 条 / 全部 '+rows.length+' 条';$('page').textContent=page+' / '+total;$('prev').disabled=page===1;$('next').disabled=page===total;$('empty').hidden=filtered.length>0;$('body').innerHTML=filtered.slice((page-1)*size,page*size).map(r=>'<tr><td><b>'+esc(r.org)+'</b><div>'+esc(r.org_unit)+'</div><span class="sub">'+esc(r.track)+' · '+esc(r.org_level)+'</span></td><td class="title"><b>'+esc(r.title)+'</b><div class="badge">'+esc(r.record_type)+'</div><details><summary>条件与证据</summary><p>'+esc(r.requirements||'尚未提取任职条件，打开来源核实。')+'</p><p>'+esc(r.duties)+'</p><p class="sub">'+esc(r.notes)+'<br>职位ID：'+esc(r.official_job_id||r.id)+'<br>本地原文：'+esc(r.evidence_file)+'</p></details></td><td>'+esc(r.locations||'地点待核实')+'<div class="sub">'+esc(r.recruitment_cycle)+'</div></td><td><span class="badge '+(r.status.startsWith('公告期限内')?'open':r.status==='已截止'?'closed':'')+'">'+esc(r.status)+'</span><div>'+esc(r.deadline||r.deadline_text||'未明确')+'</div></td><td>'+link(r.apply_url,'投递 / 查看入口')+'<br>'+link(r.source_url,'证据来源')+'<div class="sub">'+esc(r.verification)+'</div></td></tr>').join('');}
for(const id of ['query','type','track','status','year'])$(id).addEventListener('input',filter);$('prev').onclick=()=>{page--;render()};$('next').onclick=()=>{page++;render()};$('reset').onclick=()=>{for(const id of ['query','type','track','status','year'])$(id).value='';filter()};filter();</script></html>'''
for k,v in {'__JOBS__':stats['types'].get('具体岗位',0),'__OPEN__':stats['statuses'].get('公告期限内（投递前复核）',0),'__LEADS__':stats['types'].get('聚合招聘线索',0),'__TOTAL__':len(rows),'__DATA__':data}.items():template=template.replace(k,str(v))
(OUT/'岗位总览.html').write_text(template)
print(OUT/'岗位总览.html')
